        return;
    }
    visited[i][j] = true;
    markVisited(grid, visited, i - 1, j);
    markVisited(grid, visited, i + 1, j);
    markVisited(grid, visited, i, j - 1);
    markVisited(grid, visited, i, j + 1);
}
