public static int maxRegions(int N) {
    // Initialize variables
    int maxRegions = 0;
    int currentRegions;

    // Iterate over each triangle and calculate the number of regions that can be created by connecting it to its neighbors
    for (int i = 0; i < N; i++) {
        currentRegions = 0;
        for (int j = 0; j < i; j++) {
            if (canConnect(i, j)) {
                currentRegions++;
            }
        }
        maxRegions = Math.max(maxRegions, currentRegions);
    }

    return maxRegions;
}

private static boolean canConnect(int i, int j) {
    // Check if the two triangles share a common vertex
    return i % 2 == 0 && j % 2 == 0 && i / 2 == j / 2;
}

