public class CountDoubles {
    public static int countDoubles(int[] numbers) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int num : numbers) {
            int doubled = num * 2;
            Integer count = counts.get(doubled);
            if (count == null) {
                count = 0;
            }
            counts.put(doubled, count + 1);
