        int doubleCount = 0;
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() >= 2) {
                doubleCount += entry.getValue() - 1;
            }
        }

        return doubleCount;
    }
}
