public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    List<Integer>[] graph = new List[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        graph[edge[0]].add(edge[1]);
        graph[edge[1]].add(edge[0]);
    }

    // Initialize the minimum time required to collect all apples and return to node 0
    int minTime = 0;

    // Perform a depth-first search to find the shortest path to collect all apples
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor : graph[node]) {
            if (!hasApple[neighbor]) {
                continue;
            }
            int neighborTime = Math.max(hasApple[neighbor] ? 2 : 0, minTime + 1);
            minTime = Math.min(minTime, neighborTime);
            queue.offer(neighbor);
        }
    }

    return minTime;
}
