    public int maxAbsoluteSum(int[] nums) {
        int prefixSum = 0;
        int maxSum = 0;
        for (int i = 0; i < nums.length; i++) {
            prefixSum += nums[i];
            maxSum = Math.max(maxSum, Math.abs(prefixSum));
