        entities.stream()
                .filter(e -> e instanceof Encryptable)
                .forEach(e -> ((Encryptable) e).encryptSensitiveFields(secretService));
        Object result = proceedingJoinPoint.proceed();
        if (result instanceof Collection) {
            ((Collection<?>) result).stream()
