private static int dfs(int[][] mat, boolean[][] visited, int i, int j) {
    if (i < 0 || i >= mat.length || j < 0 || j >= mat[0].length || visited[i][j] || mat[i][j] != 1) {
        return 0;
    }
    visited[i][j] = true;
    return 1 + dfs(mat, visited, i + 1, j) + dfs(mat, visited, i, j + 1) + dfs(mat, visited, i - 1, j) + dfs(mat, visited, i, j - 1);
}
