public static int findFirstRegularPolygon(int n) {
    if (n <= 0) {
        return -1;
    }

    int row = 1;
    int col = 1;
    while (col < n) {
        row++;
        col = (col * 2) % (n - 1);
        if (col == 0) {
            col = 1;
        }
    }

